window.STORY_CHAPTERS["c813f4e379cb1a538"]={"id":"c813f4e379cb1a538","lines":[{"uid":"talk.kirito_1_86#originalText","id":"talk.kirito_1_86","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"Mission complete!","en":"Mission complete!","ja":"Mission complete!"},"kind":"caption"},{"uid":"talk.kirito_1_00#originalText","id":"talk.kirito_1_00","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"「牵手约会」","en":"Hand-Holding","ja":"「手繋ぎデート」"},"kind":"caption"},{"uid":"talk.kirito_1_01#originalText","id":"talk.kirito_1_01","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"难得今天没半个人过来耶。","en":"Weird that nobody's here today.","ja":"今日は珍しく誰も来ないね"},"kind":"dialogue"},{"uid":"talk.kirito_1_02#originalText","id":"talk.kirito_1_02","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"毕竟最近每天都会有人来嘛。","en":"Probably feels weird since someone's been here every day lately.","ja":"ここのところ毎日誰か来てたからなあ"},"kind":"dialogue"},{"uid":"talk.kirito_1_03#originalText","id":"talk.kirito_1_03","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"爸爸和妈妈要不要出去走走？你们最近都没有时间独处呢。","en":"Daddy, Mommy, why don't you two go on an outing? You haven't had much alone-time recently.","ja":"パパとママ、ふたりでお出かけしたらどうですか? 最近ずっと、ふたりになっていませんし"},"kind":"dialogue"},{"uid":"talk.kirito_1_04#originalText","id":"talk.kirito_1_04","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"结衣……","en":"Yui...","ja":"ユイちゃん……"},"kind":"dialogue"},{"uid":"talk.kirito_1_05#originalText","id":"talk.kirito_1_05","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"那我们就接受结衣的好意，出去走走吧，桐人。","en":"I think I'll take you up on that. Wanna go, Kirito?","ja":"それじゃ、お言葉に甘えて行こうか、キリトくん"},"kind":"dialogue"},{"uid":"talk.kirito_1_06#originalText","id":"talk.kirito_1_06","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"像这样走着，就会想起我们在艾恩葛朗特的时候呢。","en":"Walking around with you like this really takes me back to our Aincrad days.","ja":"こうやって歩いていると、思い出すなあ。アインクラッドでのこと"},"kind":"dialogue"},{"uid":"talk.kirito_1_07#originalText","id":"talk.kirito_1_07","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"那可是我们两个第一次买的家嘛。","en":"Well, this was the first house we bought together, too.","ja":"初めてふたりで買った家、だもんな"},"kind":"dialogue"},{"uid":"talk.kirito_1_08#originalText","id":"talk.kirito_1_08","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"那时也是像这样一起散着步……","en":"I remember we were walking like this, and then...","ja":"あの時も、こうやって散歩して……"},"kind":"dialogue"},{"uid":"talk.kirito_1_08#selectionText1","id":"talk.kirito_1_08","speaker":{"cn":"[1]","en":"[1]","ja":"[1]"},"text":{"cn":"你当时还有背我呢","en":"You carried me on your back.","ja":"わたしのこと、おんぶしてくれたよね"},"kind":"dialogue"},{"uid":"talk.kirito_1_08#selectionText2","id":"talk.kirito_1_08","speaker":{"cn":"[2]","en":"[2]","ja":"[2]"},"text":{"cn":"你当时还让我坐在肩膀上呢","en":"You carried me on your shoulders.","ja":"わたしのこと、肩車してくれたよね"},"kind":"dialogue"},{"uid":"talk.kirito_1_09#originalText","id":"talk.kirito_1_09","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"你当时还有背我呢","en":"You carried me on your back.","ja":"わたしのこと、おんぶしてくれたよね"},"kind":"dialogue"},{"uid":"talk.kirito_1_10#originalText","id":"talk.kirito_1_10","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"你当时还让我坐在肩膀上呢","en":"You carried me on your shoulders.","ja":"わたしのこと、肩車してくれたよね"},"kind":"dialogue"},{"uid":"talk.kirito_1_11#originalText","id":"talk.kirito_1_11","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"背妳……有这回事吗？","en":"On my back...? Was it really like that?","ja":"おんぶ……そうだったっけ?"},"kind":"dialogue"},{"uid":"talk.kirito_1_12#originalText","id":"talk.kirito_1_12","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"哎呀，是我记错了吗……","en":"Oops, did I misremember?","ja":"あれ、違ったかしら……"},"kind":"dialogue"},{"uid":"talk.kirito_1_13#originalText","id":"talk.kirito_1_13","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"毕竟是满久之前的事了，记错也不奇怪嘛。","en":"Well, it was so long ago I don't blame you.","ja":"まあ、結構昔の話だし、しょうがないよ"},"kind":"dialogue"},{"uid":"talk.kirito_1_14#originalText","id":"talk.kirito_1_14","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"说不定会有人来，我们差不多该回去了吧。","en":"Maybe we should head back. Someone might show up.","ja":"誰か来るかもしれないし、そろそろ戻ろうか"},"kind":"dialogue"},{"uid":"talk.kirito_1_15#originalText","id":"talk.kirito_1_15","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"啊，桐人……","en":"Oh! Kirito...","ja":"あっ、キリトくん……"},"kind":"dialogue"},{"uid":"talk.kirito_1_16#originalText","id":"talk.kirito_1_16","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"是啊，妳突然说想坐在我的肩膀上，吓了我一跳。","en":"Yeah, I remember. You caught me off guard when you asked for a shoulder ride out of nowhere.","ja":"そうだったなあ、アスナがいきなり「肩車して」なんていうからビックリしたよ"},"kind":"dialogue"},{"uid":"talk.kirito_1_17#originalText","id":"talk.kirito_1_17","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"呵呵，其实当时……是有点想撒娇。而且我以为没有其他人。","en":"Haha... Well, confession time. I just wanted you to fawn on me. Besides, I thought we were alone.","ja":"ふふ、あの時はね……ちょっと甘えたかったの誰もいないと思ったし"},"kind":"dialogue"},{"uid":"talk.kirito_1_18#originalText","id":"talk.kirito_1_18","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"湖边明明就有很多人在钓鱼啊。","en":"Even though there were plenty of fishermen around the lake.","ja":"湖の周りには、たくさんいたけどな釣り人が"},"kind":"dialogue"},{"uid":"talk.kirito_1_19#originalText","id":"talk.kirito_1_19","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"可是……我真的没想到会有那么多人嘛。","en":"In my defense, I never dreamed there'd be so many!","ja":"だって……あんなにいるなんて思わなかったんだもん!"},"kind":"dialogue"},{"uid":"talk.kirito_1_20#originalText","id":"talk.kirito_1_20","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"那好像是艾恩葛朗特相当知名的钓点。","en":"Well, it was a pretty popular fishing spot in Aincrad.","ja":"けっこう有名な釣りスポットだったんだよなアインクラッドでは"},"kind":"dialogue"},{"uid":"talk.kirito_1_21#originalText","id":"talk.kirito_1_21","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"毕竟22层没什么怪物出没，可以安心地钓鱼。","en":"That makes sense, seeing as how the 22nd Floor was pretty safe, with nary a monster in sight.","ja":"22層は、あんまりモンスターも出ないし安全に釣りができるもんね"},"kind":"dialogue"},{"uid":"talk.kirito_1_22#originalText","id":"talk.kirito_1_22","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"不知道ALO是不是也一样？之后去看看好了。","en":"Is this the case in ALO as well? Perhaps we should look into it later.","ja":"ALOでもそうなのかな?後で調べてみよっか"},"kind":"dialogue"},{"uid":"talk.kirito_1_23#originalText","id":"talk.kirito_1_23","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"说不定西田先生也在那里。","en":"Would be hilarious if we ran into Nishida again.","ja":"案外、またニシダさんがいたりして"},"kind":"dialogue"},{"uid":"talk.kirito_1_24#originalText","id":"talk.kirito_1_24","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"西田先生！真怀念～不知道他过得好不好。","en":"Nishida! That's a name I haven't heard in a while. I wonder how he's doing?","ja":"ニシダさん!懐かしい～、お元気かな"},"kind":"dialogue"},{"uid":"talk.kirito_1_25#originalText","id":"talk.kirito_1_25","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"那些人应该已经顺利脱离了吧？毕竟这里挺安全的。","en":"Do you think they all made it out safe? Seems like they would.","ja":"あの人たち、無事に脱出できてるよなここなら安全だし"},"kind":"dialogue"},{"uid":"talk.kirito_1_25#selectionText1","id":"talk.kirito_1_25","speaker":{"cn":"[1]","en":"[1]","ja":"[1]"},"text":{"cn":"那当然，他们一定没事的！","en":"Of course they escaped!","ja":"もちろん、そうに決まってるよ!"},"kind":"dialogue"},{"uid":"talk.kirito_1_25#selectionText2","id":"talk.kirito_1_25","speaker":{"cn":"[2]","en":"[2]","ja":"[2]"},"text":{"cn":"这……说不准呢","en":"Well...I'm not really sure.","ja":"それは……わからないかも"},"kind":"dialogue"},{"uid":"talk.kirito_1_26#originalText","id":"talk.kirito_1_26","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"那当然，他们一定没事的！","en":"Of course they escaped!","ja":"もちろん、そうに決まってるよ!"},"kind":"dialogue"},{"uid":"talk.kirito_1_27#originalText","id":"talk.kirito_1_27","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"这……说不准呢","en":"Well...I'm not really sure.","ja":"それは……わからないかも"},"kind":"dialogue"},{"uid":"talk.kirito_1_28#originalText","id":"talk.kirito_1_28","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"……的确，妳说得对。在艾恩葛朗特，没有人知道会发生什么事。","en":"Yeah...good point. There was just no telling what might happen in Aincrad.","ja":"……確かに、そうだよなアインクラッドじゃ、何が起こるかわからない"},"kind":"dialogue"},{"uid":"talk.kirito_1_29#originalText","id":"talk.kirito_1_29","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"……嗯。啊，不过他们肯定会平安无事的……","en":"Yeah... Oh, but I'm hopeful they did...","ja":"……うんあ、でもきっと……"},"kind":"dialogue"},{"uid":"talk.kirito_1_30#originalText","id":"talk.kirito_1_30","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"……感觉话题好像突然沉重了起来。差不多该回去了吧。","en":"Well, that turned morbid pretty fast. We should probably head back.","ja":"……なんだか湿っぽい話になっちゃったなそろそろ戻ろうか"},"kind":"dialogue"},{"uid":"talk.kirito_1_31#originalText","id":"talk.kirito_1_31","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"啊，桐人……","en":"Oh! Kirito...","ja":"あっ、キリトくん……"},"kind":"dialogue"},{"uid":"talk.kirito_1_32#originalText","id":"talk.kirito_1_32","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我想也是！他在现实世界里，应该也正在享受着钓鱼的乐趣吧──","en":"Yeah, of course! And I'm sure they're all having fun fishing in real life now.","ja":"だよな!現実世界でも、釣りを楽しんでるんだろうなー"},"kind":"dialogue"},{"uid":"talk.kirito_1_33#originalText","id":"talk.kirito_1_33","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"呵呵，桐人你要不要也试试？","en":"Haha. Wanna fish, Kirito?","ja":"ふふ、キリトくんもやってみたら?"},"kind":"dialogue"},{"uid":"talk.kirito_1_34#originalText","id":"talk.kirito_1_34","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"钓鱼实在是不太适合我……","en":"I could never get the hang of it.","ja":"釣りは、どうも相性がなあ……"},"kind":"dialogue"},{"uid":"talk.kirito_1_35#originalText","id":"talk.kirito_1_35","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"西田先生一直很想钓到湖之主人呢。直到和你联手才终于钓到……","en":"Nishida's goal all along was to take down the King of Lakes. You two worked well together...","ja":"ニシダさん、ずっと、湖の主を狙ってたんだよね。キリトくんと協力してようやく釣り上げて……"},"kind":"dialogue"},{"uid":"talk.kirito_1_35#selectionText1","id":"talk.kirito_1_35","speaker":{"cn":"[1]","en":"[1]","ja":"[1]"},"text":{"cn":"湖之主人是桐人解决掉的对吧？","en":"...and finally defeated it, right?","ja":"あの湖の主、キリトくんが倒したんだよね"},"kind":"dialogue"},{"uid":"talk.kirito_1_35#selectionText2","id":"talk.kirito_1_35","speaker":{"cn":"[2]","en":"[2]","ja":"[2]"},"text":{"cn":"不过，和湖之主人一战，还真有点可怕！","en":"Still, fighting that boss was kind of scary, you know?","ja":"でも、あの主と戦うの、ちょっと怖かったんだから!"},"kind":"dialogue"},{"uid":"talk.kirito_1_36#originalText","id":"talk.kirito_1_36","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"湖之主人是桐人解决掉的对吧？","en":"...and finally defeated it, right?","ja":"あの湖の主、キリトくんが倒したんだよね"},"kind":"dialogue"},{"uid":"talk.kirito_1_37#originalText","id":"talk.kirito_1_37","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"不过，和湖之主人一战，还真有点可怕！","en":"Still, fighting that boss was kind of scary, you know?","ja":"でも、あの主と戦うの、ちょっと怖かったんだから!"},"kind":"dialogue"},{"uid":"talk.kirito_1_38#originalText","id":"talk.kirito_1_38","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"咦？解决掉牠的是妳吧？我当时根本没带武器。","en":"Huh? Weren't you the one who defeated the boss? I didn't even have a weapon on me.","ja":"え、あの主を倒したのはアスナだろう?俺、武器持ってなかったし"},"kind":"dialogue"},{"uid":"talk.kirito_1_39#originalText","id":"talk.kirito_1_39","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"咦，是吗……？我怎么记得是你打倒牠的？","en":"Oh, wait, really? I could have sworn it was you...","ja":"あれ、そうだったかな……なんか、キリトくんが倒してくれたような"},"kind":"dialogue"},{"uid":"talk.kirito_1_40#originalText","id":"talk.kirito_1_40","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"不对，是亚丝娜啦。大家不是还夸了妳一番吗？","en":"No, you did it, Asuna. Remember how you dazzled everyone?","ja":"いや、アスナだよみんなに褒められてたじゃないか"},"kind":"dialogue"},{"uid":"talk.kirito_1_41#originalText","id":"talk.kirito_1_41","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"是这样吗……？","en":"Did I?","ja":"そうだっけ……"},"kind":"dialogue"},{"uid":"talk.kirito_1_42#originalText","id":"talk.kirito_1_42","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"亚丝娜，妳是不是有点累了？回家休息一下吧。","en":"Asuna...are you tired? Maybe we should go back and take it easy.","ja":"アスナ、ちょっと疲れてるのか?戻って、少し休もうか"},"kind":"dialogue"},{"uid":"talk.kirito_1_43#originalText","id":"talk.kirito_1_43","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"啊，桐人……","en":"Oh! Kirito...","ja":"あっ、キリトくん……"},"kind":"dialogue"},{"uid":"talk.kirito_1_44#originalText","id":"talk.kirito_1_44","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"抱歉，我当时没带武器……我根本没想到会要战斗。","en":"Sorry I didn't have a weapon... I never dreamed we would need to fight.","ja":"ごめん、俺が武器を持って無くて……まさか、戦闘になるなんて思ってなかったから"},"kind":"dialogue"},{"uid":"talk.kirito_1_45#originalText","id":"talk.kirito_1_45","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"不、不过……以亚丝娜的实力，湖之主人完全不是对手吧……？","en":"B-But you know, Asuna, I'm sure that the King of Lakes was child's play to someone with your skill.","ja":"で、でもさ……アスナの実力なら、湖の主だって楽勝だったんじゃ……"},"kind":"dialogue"},{"uid":"talk.kirito_1_46#originalText","id":"talk.kirito_1_46","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"话不是这样说的！牠长得那么可怕，而且我还穿便服……","en":"He was not child's play! Don't you remember how it looked? And I wasn't dressed for battle.","ja":"そういうことじゃありません!あんな見た目の怪物と、しかも私服で……"},"kind":"dialogue"},{"uid":"talk.kirito_1_47#originalText","id":"talk.kirito_1_47","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"怎么可能会不怕啊？","en":"Of course I was terrified!","ja":"怖いに決まってるでしょう"},"kind":"dialogue"},{"uid":"talk.kirito_1_48#originalText","id":"talk.kirito_1_48","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"……唔，抱歉。","en":"Ouch... Sorry.","ja":"……うう、すみません"},"kind":"dialogue"},{"uid":"talk.kirito_1_49#originalText","id":"talk.kirito_1_49","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"……嗯，没关系。","en":"It's cool, I forgive you. I just hope you learned your lesson.","ja":"……うん、許してあげる"},"kind":"dialogue"},{"uid":"talk.kirito_1_49_2#originalText","id":"talk.kirito_1_49_2","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"但是武器得要随身带着才行。","en":"Always carry a weapon.","ja":"武器はいつでも持ち歩かないとね"},"kind":"dialogue"},{"uid":"talk.kirito_1_50#originalText","id":"talk.kirito_1_50","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"是……","en":"Yes, ma'am...","ja":"はい……"},"kind":"dialogue"},{"uid":"talk.kirito_1_50_2#originalText","id":"talk.kirito_1_50_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"不过我还挺好奇湖之主人的滋味如何，可惜那时没吃到。","en":"But I still wonder what it tasted like. We missed out on that after party.","ja":"でも、あの主は味も気になるよなあの時は食べ損なっちゃったけど"},"kind":"dialogue"},{"uid":"talk.kirito_1_51#originalText","id":"talk.kirito_1_51","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"咦？你……想吃那个东西？","en":"Huh? ...Is something like that even edible?","ja":"え、アレを……食べるの?"},"kind":"dialogue"},{"uid":"talk.kirito_1_52#originalText","id":"talk.kirito_1_52","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我想说搞不好其实很好吃……而且，调理过后就不必在意原本的长相了！","en":"I don't see why not? Besides, doesn't matter how gross it looks once it's cooked!","ja":"案外いけると思うんだけど……それに、料理しちゃえば見た目は関係ないし!"},"kind":"dialogue"},{"uid":"talk.kirito_1_53#originalText","id":"talk.kirito_1_53","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"呃……","en":"Eww...","ja":"うう……"},"kind":"dialogue"},{"uid":"talk.kirito_1_53#selectionText1","id":"talk.kirito_1_53","speaker":{"cn":"[1]","en":"[1]","ja":"[1]"},"text":{"cn":"要吃也可以，不过你要负责下厨哦","en":"Okay, fine. But only if you do the cooking.","ja":"いいけど、キリトくんが料理してね"},"kind":"dialogue"},{"uid":"talk.kirito_1_53#selectionText2","id":"talk.kirito_1_53","speaker":{"cn":"[2]","en":"[2]","ja":"[2]"},"text":{"cn":"那就找大家一起来吃吧！这样每个人都只要吃一点就好！","en":"Then let's invite the others over! At least the portions will be smaller that way.","ja":"なら、みんなにも来てもらおう!それなら、ひとりあたりの食べる量は少なくなるし!"},"kind":"dialogue"},{"uid":"talk.kirito_1_54#originalText","id":"talk.kirito_1_54","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"要吃也可以，不过你要负责下厨哦","en":"Okay, fine. But only if you do the cooking.","ja":"いいけど、キリトくんが料理してね"},"kind":"dialogue"},{"uid":"talk.kirito_1_55#originalText","id":"talk.kirito_1_55","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"那就找大家一起来吃吧！这样每个人都只要吃一点就好！","en":"Then let's invite the others over! At least the portions will be smaller that way.","ja":"なら、みんなにも来てもらおう!それなら、ひとりあたりの食べる量は少なくなるし!"},"kind":"dialogue"},{"uid":"talk.kirito_1_56#originalText","id":"talk.kirito_1_56","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"好，那就这么决定了！","en":"Cool. It's a plan!","ja":"よし、なら決まりだな!"},"kind":"dialogue"},{"uid":"talk.kirito_1_57#originalText","id":"talk.kirito_1_57","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"不过，我绝对不要处理那只鱼哦！","en":"Just to be clear, I'm not doing the gutting and cleaning. Not in a million years!","ja":"でも、わたしはさばきませんからね絶対に!"},"kind":"dialogue"},{"uid":"talk.kirito_1_58#originalText","id":"talk.kirito_1_58","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我、我知道啦……叫艾基尔来处理好了。","en":"S-Sure, I get it. Maybe Agil would take on that job.","ja":"わ、わかってるよ……エギルにでもやらせるか"},"kind":"dialogue"},{"uid":"talk.kirito_1_59#originalText","id":"talk.kirito_1_59","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"爸爸、妈妈！","en":"Daddy! Mommy!","ja":"パパ、ママ!"},"kind":"dialogue"},{"uid":"talk.kirito_1_60#originalText","id":"talk.kirito_1_60","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"啊，结衣！","en":"Oh! Hi, Yui!","ja":"あっ、ユイちゃん!"},"kind":"dialogue"},{"uid":"talk.kirito_1_61#originalText","id":"talk.kirito_1_61","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"你们一起去散步了呀。抱歉打扰了，但大家都到小木屋来了。","en":"You two were on a walk, I see! I hate to intrude, but everyone has assembled in the log house.","ja":"ふたりでお散歩してたんですね楽しそうですけど、ログハウスにみなさん来てます"},"kind":"dialogue"},{"uid":"talk.kirito_1_62#originalText","id":"talk.kirito_1_62","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"他们好像在等你们……","en":"They seem to be waiting for you.","ja":"パパとママを待ってるみたいですけど……"},"kind":"dialogue"},{"uid":"talk.kirito_1_62#selectionText1","id":"talk.kirito_1_62","speaker":{"cn":"[1]","en":"[1]","ja":"[1]"},"text":{"cn":"那我们回去吧，桐人","en":"Then let's go back. Shall we, Kirito?","ja":"なら、戻ろうかキリトくん"},"kind":"dialogue"},{"uid":"talk.kirito_1_62#selectionText2","id":"talk.kirito_1_62","speaker":{"cn":"[2]","en":"[2]","ja":"[2]"},"text":{"cn":"我们今天就这样……继续散步怎么样？","en":"Hey, can we just... keep walking the rest of the day?","ja":"ねえ、今日はこのまま……お散歩しない?"},"kind":"dialogue"},{"uid":"talk.kirito_1_63#originalText","id":"talk.kirito_1_63","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"那我们回去吧，桐人","en":"Then let's go back. Shall we, Kirito?","ja":"なら、戻ろうかキリトくん"},"kind":"dialogue"},{"uid":"talk.kirito_1_64#originalText","id":"talk.kirito_1_64","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"我们今天就这样……继续散步怎么样？","en":"Hey, can we just... keep walking the rest of the day?","ja":"ねえ、今日はこのまま……お散歩しない?"},"kind":"dialogue"},{"uid":"talk.kirito_1_65#originalText","id":"talk.kirito_1_65","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"说得也是，虽然还想继续散步……","en":"Good idea. As much as I'd love to keep walking.","ja":"そうだな、散歩も名残惜しいけど……"},"kind":"dialogue"},{"uid":"talk.kirito_1_66#originalText","id":"talk.kirito_1_66","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"下次再一起来吧。","en":"We can come back some other time.","ja":"今度、また来ましょう"},"kind":"dialogue"},{"uid":"talk.kirito_1_67#originalText","id":"talk.kirito_1_67","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"到时候也要带上我哦！","en":"And I would love to join you when that time comes!","ja":"そのときは、私も連れて行ってください!"},"kind":"dialogue"},{"uid":"talk.kirito_1_68#originalText","id":"talk.kirito_1_68","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"……嗯，偶尔为之应该没关系。","en":"Good idea... It's nice to mix things up a little.","ja":"……そうだな、たまにはいいか"},"kind":"dialogue"},{"uid":"talk.kirito_1_69#originalText","id":"talk.kirito_1_69","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"嗯，我好开心哦。","en":"Cool. I'm glad you agree.","ja":"うん、うれしい"},"kind":"dialogue"},{"uid":"talk.kirito_1_70#originalText","id":"talk.kirito_1_70","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"………………","en":"......","ja":"………………"},"kind":"dialogue"},{"uid":"talk.kirito_1_71#originalText","id":"talk.kirito_1_71","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"那我们全家一起到湖边去吧！","en":"Okay, let's make this a family outing to the lake!","ja":"それじゃ、家族みんなで湖に行くぞ!"},"kind":"dialogue"},{"uid":"talk.kirito_1_72#originalText","id":"talk.kirito_1_72","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"喔──！","en":"Yaaay!","ja":"おー!"},"kind":"dialogue"},{"uid":"talk.kirito_1_73#originalText","id":"talk.kirito_1_73","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"开心归开心……但我要先回大家那里去了。","en":"I appreciate it too... But I'm going to return to where the others are.","ja":"うれしいですけど……私はみなさんのところに戻ります"},"kind":"dialogue"},{"uid":"talk.kirito_1_74#originalText","id":"talk.kirito_1_74","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"我去告诉他们爸爸和妈妈暂时不会回来。","en":"I'll tell them that you will be away for a while.","ja":"パパとママは、しばらく戻りませんって伝えてきます"},"kind":"dialogue"},{"uid":"talk.kirito_1_75#originalText","id":"talk.kirito_1_75","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"咦？结衣，妳也一起……","en":"Huh? But Yui, you should come...","ja":"えっ、ユイちゃんも一緒に……"},"kind":"dialogue"},{"uid":"talk.kirito_1_76#originalText","id":"talk.kirito_1_76","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"爸爸和妈妈今天就两个人好好约会吧！","en":"Daddy, Mommy, I insist. Please have a nice date together!","ja":"今日は、パパとママふたりでデートしてきてください!"},"kind":"dialogue"},{"uid":"talk.kirito_1_77#originalText","id":"talk.kirito_1_77","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"结衣……","en":"Yui...","ja":"ユイ……"},"kind":"dialogue"},{"uid":"talk.kirito_1_78#originalText","id":"talk.kirito_1_78","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"那你们好好享受约会时光吧！爸爸、妈妈！","en":"Well, have a good time, Daddy, Mommy!","ja":"それじゃ、ごゆっくりです!パパ、ママ!"},"kind":"dialogue"},{"uid":"talk.kirito_1_79#originalText","id":"talk.kirito_1_79","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"啊，结衣……","en":"Oh! Yui...","ja":"あっ、ユイちゃん……"},"kind":"dialogue"},{"uid":"talk.kirito_1_80#originalText","id":"talk.kirito_1_80","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"让结衣费心了呢。","en":"I feel kind of guilty that Yui felt like she had to give us space.","ja":"ユイに気を遣わせちゃったな"},"kind":"dialogue"},{"uid":"talk.kirito_1_81#originalText","id":"talk.kirito_1_81","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"嗯……不过，我很开心。","en":"Yeah... But I'm grateful she did.","ja":"うん……でも、うれしい"},"kind":"dialogue"},{"uid":"talk.kirito_1_82#originalText","id":"talk.kirito_1_82","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"难得结衣一片好意，我们就好好共度两人时光吧。","en":"Yui was really sweet to give us time for a date. We can't waste a moment of it.","ja":"せっかくのユイからのプレゼントだ大事に過ごさないとな"},"kind":"dialogue"},{"uid":"talk.kirito_1_83#originalText","id":"talk.kirito_1_83","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"……呐，桐人。我可以……牵你的手吗？","en":"Hey, Kirito... Can we...hold hands?","ja":"……ね、キリトくん手……繋いでもいい?"},"kind":"dialogue"},{"uid":"talk.kirito_1_84#originalText","id":"talk.kirito_1_84","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"当然可以啊，亚丝娜。","en":"Of course, Asuna.","ja":"もちろんだよ、アスナ"},"kind":"dialogue"},{"uid":"talk.kirito_1_85#originalText","id":"talk.kirito_1_85","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"呵呵……真开心。","en":"Hehe...thanks.","ja":"ふふ……うれしい"},"kind":"dialogue"},{"uid":"talk.kirito_2_00#originalText","id":"talk.kirito_2_00","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"「好像有种奇怪的感觉」","en":"An Odd Feeling","ja":"「なんだか、変な気分」"},"kind":"caption"},{"uid":"talk.kirito_2_01#originalText","id":"talk.kirito_2_01","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"……喝！","en":"Hah!","ja":"……はっ!"},"kind":"dialogue"},{"uid":"talk.kirito_2_02#originalText","id":"talk.kirito_2_02","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"……啊！","en":"Haaah!","ja":"……はあっ!"},"kind":"dialogue"},{"uid":"talk.kirito_2_03#originalText","id":"talk.kirito_2_03","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"……这样根本不行。","en":"No...it's not enough.","ja":"……ダメだ、こんなんじゃ"},"kind":"dialogue"},{"uid":"talk.kirito_2_04#originalText","id":"talk.kirito_2_04","speaker":{"cn":"？？？","en":"???","ja":"？？？"},"text":{"cn":"尤吉欧修剑士！今天可是安息日喔！","en":"Trainee Swordsman Eugeo! Today is a day of rest!","ja":"ユージオ修剣士!今日は安息日ですよ!"},"kind":"dialogue"},{"uid":"talk.kirito_2_05#originalText","id":"talk.kirito_2_05","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"咦！？啊，对不起……","en":"Huh?! I-I'm sorry...","ja":"えっ!?あっ、すみません……"},"kind":"dialogue"},{"uid":"talk.kirito_2_06#originalText","id":"talk.kirito_2_06","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"……开玩笑的。是我啦，是我。","en":"Just kidding. It's me, Eugeo.","ja":"……なーんて俺だよ、俺"},"kind":"dialogue"},{"uid":"talk.kirito_2_07#originalText","id":"talk.kirito_2_07","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"原、原来是桐人啊……你别吓我好不好。","en":"O-Oh, it's just you, Kirito... Stop scaring me like that.","ja":"な、なんだキリトか……驚かさないでくれよ"},"kind":"dialogue"},{"uid":"talk.kirito_2_08#originalText","id":"talk.kirito_2_08","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"在安息日挥剑是违反学院规范的。要是让别人看到，事情可就严重了。","en":"But training on a day of rest is against academy rules. You'd be in trouble if someone else found you.","ja":"安息日に剣を振るのは、学院則違反だぞ俺じゃなかったら大変なことになってたところだ"},"kind":"dialogue"},{"uid":"talk.kirito_2_08#selectionText1","id":"talk.kirito_2_08","speaker":{"cn":"[1]","en":"[1]","ja":"[1]"},"text":{"cn":"嘴巴上这么说，你自己还不是常常在偷练","en":"Well, you practice with your sword plenty on days of rest, Kirito.","ja":"そんなこと言って、キリトだってよく剣を振っているじゃないか"},"kind":"dialogue"},{"uid":"talk.kirito_2_08#selectionText2","id":"talk.kirito_2_08","speaker":{"cn":"[2]","en":"[2]","ja":"[2]"},"text":{"cn":"………………","en":"......","ja":"………………"},"kind":"dialogue"},{"uid":"talk.kirito_2_09#originalText","id":"talk.kirito_2_09","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"嘴巴上这么说，你自己还不是常常在偷练","en":"Well, you practice with your sword plenty on days of rest, Kirito.","ja":"そんなこと言って、キリトだってよく剣を振っているじゃないか"},"kind":"dialogue"},{"uid":"talk.kirito_2_10#originalText","id":"talk.kirito_2_10","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"………………","en":"......","ja":"………………"},"kind":"dialogue"},{"uid":"talk.kirito_2_11#originalText","id":"talk.kirito_2_11","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"怎么？什么事让你这么烦恼？这种时候挥剑也不能解决问题喔。","en":"Something bugging you? Swinging a sword won't fix that, you know?","ja":"なんだよ、よっぽど悩んでるのか?そんな時に剣を振っても無駄だぜ?"},"kind":"dialogue"},{"uid":"talk.kirito_2_12#originalText","id":"talk.kirito_2_12","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"好，我们去城里买东西吧。这种时候就该吃点好吃的！","en":"Okay, let's go shopping. Good food is the best cure when you're in a funk!","ja":"よし、これから街へ買い物に行こうこういう時はうまいものを食うに限る!"},"kind":"dialogue"},{"uid":"talk.kirito_2_13#originalText","id":"talk.kirito_2_13","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"啊，等一下啦！桐人！我……","en":"Ah! Wait a minute, Kirito! I'm not...","ja":"あっ、ちょっと待ってくれよキリト!僕は……"},"kind":"dialogue"},{"uid":"talk.kirito_2_14#originalText","id":"talk.kirito_2_14","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"好啦好啦！我们走吧，尤吉欧！","en":"Come on, no excuses. Let's go, Eugeo!","ja":"いいから、いいから!ほら、行くぞユージオ!"},"kind":"dialogue"},{"uid":"talk.kirito_2_15#originalText","id":"talk.kirito_2_15","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"不不不，我可是有好好躲起来呢……","en":"Yeah, well, at least I practice where nobody will find me.","ja":"いやいや、俺は見つからないようにだな……"},"kind":"dialogue"},{"uid":"talk.kirito_2_16#originalText","id":"talk.kirito_2_16","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"真是的，说这什么话！要是哪天被发现了，我可不管你。","en":"You're always so reckless! Don't come complaining to me when you get caught.","ja":"まったく、そんなこと言って!いつか見つかっても知らないからね、僕は"},"kind":"dialogue"},{"uid":"talk.kirito_2_17#originalText","id":"talk.kirito_2_17","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"是是是。不过，真的很难得看到你这个样子，发生什么事了？","en":"Yes, sir. But this really is unlike you. Did something happen?","ja":"はいはいでも、ホントに珍しいよな。何かあったのか?"},"kind":"dialogue"},{"uid":"talk.kirito_2_18#originalText","id":"talk.kirito_2_18","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"也没什么……只是在想点事情。","en":"Not really... I just had something on my mind.","ja":"いや、別に……ちょっと考え事してただけだよ"},"kind":"dialogue"},{"uid":"talk.kirito_2_19#originalText","id":"talk.kirito_2_19","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"心情郁闷的时候，挥剑就会有种平静下来的感觉……","en":"Whenever my mind is racing, swinging a sword calms me somehow.","ja":"モヤモヤしている時は、剣を振るとなんだか落ち着くから……"},"kind":"dialogue"},{"uid":"talk.kirito_2_20#originalText","id":"talk.kirito_2_20","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"原来如此。我懂你的心情。","en":"Yeah, I get that.","ja":"なるほどなその気持ちは俺もわかる"},"kind":"dialogue"},{"uid":"talk.kirito_2_21#originalText","id":"talk.kirito_2_21","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"那我知道有个好地方。虽然是我的秘密基地，但特别为你破例。","en":"Then I've got the place for you. It's kind of my secret hideaway, but I'll let you in on it.","ja":"だったら、いい場所があるぜ秘密の場所だけど、ユージオは特別だ"},"kind":"dialogue"},{"uid":"talk.kirito_2_22#originalText","id":"talk.kirito_2_22","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"跟我来吧，尤吉欧！","en":"Follow me, Eugeo!","ja":"ついて来いよ、ユージオ!"},"kind":"dialogue"},{"uid":"talk.kirito_2_22#selectionText1","id":"talk.kirito_2_22","speaker":{"cn":"[1]","en":"[1]","ja":"[1]"},"text":{"cn":"桐人的秘密基地……真令人好奇","en":"Your secret hideaway...? Now you've got me curious.","ja":"キリトの秘密の場所……それは気になるな"},"kind":"dialogue"},{"uid":"talk.kirito_2_22#selectionText2","id":"talk.kirito_2_22","speaker":{"cn":"[2]","en":"[2]","ja":"[2]"},"text":{"cn":"桐人的秘密基地……果然还是算了","en":"Your secret hideaway...? I think I'd better pass.","ja":"キリトの秘密の場所……やっぱり止めておくよ"},"kind":"dialogue"},{"uid":"talk.kirito_2_23#originalText","id":"talk.kirito_2_23","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"桐人的秘密基地……真令人好奇","en":"Your secret hideaway...? Now you've got me curious.","ja":"キリトの秘密の場所……それは気になるな"},"kind":"dialogue"},{"uid":"talk.kirito_2_24#originalText","id":"talk.kirito_2_24","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"桐人的秘密基地……果然还是算了","en":"Your secret hideaway...? I think I'd better pass.","ja":"キリトの秘密の場所……やっぱり止めておくよ"},"kind":"dialogue"},{"uid":"talk.kirito_2_25#originalText","id":"talk.kirito_2_25","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"什么嘛，真不给面子。那我们还是到城里去吧。","en":"What? You're no fun. Okay, wanna go to town to shop instead?","ja":"なんだよ、連れないなあそれじゃ、やっぱり街にでも行くか"},"kind":"dialogue"},{"uid":"talk.kirito_2_26#originalText","id":"talk.kirito_2_26","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"走，一起去吃个饭吧，尤吉欧。","en":"Come on, Eugeo, let's go get something to eat.","ja":"さあ、飯でも食いに行こうぜ、ユージオ"},"kind":"dialogue"},{"uid":"talk.kirito_2_27#originalText","id":"talk.kirito_2_27","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"好，先往这边走。","en":"Okay, first, come this way.","ja":"よし、まずはこっちだ"},"kind":"dialogue"},{"uid":"talk.kirito_2_28#originalText","id":"talk.kirito_2_28","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"咦？要离开学院吗？","en":"Huh? We're leaving the academy?","ja":"え、学院を出るのかい?"},"kind":"dialogue"},{"uid":"talk.kirito_2_29#originalText","id":"talk.kirito_2_29","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"进到这个小巷里……","en":"Just walk down this alley and...","ja":"この路地を入って……"},"kind":"dialogue"},{"uid":"talk.kirito_2_30#originalText","id":"talk.kirito_2_30","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"桐人，我怎么觉得人好像越来越少……","en":"Kirito, is it just me or are we getting further and further away from the crowd?","ja":"キリト、なんだかどんどん人気の無い場所に来てる気がするんだけど……"},"kind":"dialogue"},{"uid":"talk.kirito_2_31#originalText","id":"talk.kirito_2_31","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"要偷偷挥剑，当然得找没人的地方吧？","en":"Of course we're getting away from the crowd. We have to, to practice in secret, right?","ja":"人に知られないように剣を振るんだから当たり前だろ?"},"kind":"dialogue"},{"uid":"talk.kirito_2_32#originalText","id":"talk.kirito_2_32","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"你说的是有道理……但这里真的可以进来吗？","en":"Well, sure, but... Is it really okay for us to be here?","ja":"そうかもしれないけど……ここ、入って大丈夫なの?"},"kind":"dialogue"},{"uid":"talk.kirito_2_33#originalText","id":"talk.kirito_2_33","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我们到了，尤吉欧。这里就是秘密基地。","en":"This is it, Eugeo. My secret hideout.","ja":"着いたぞ、ユージオここが秘密の場所だ"},"kind":"dialogue"},{"uid":"talk.kirito_2_34#originalText","id":"talk.kirito_2_34","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"央都的中心处居然有这样的森林……？这里不是商业区吗？","en":"A forest...right in the middle of the city? We're in a shopping district, right?","ja":"央都の真ん中に、こんな森が……?ここ、商業区だよね?"},"kind":"dialogue"},{"uid":"talk.kirito_2_35#originalText","id":"talk.kirito_2_35","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"可能因为这里离所有道路都有段距离，不知不觉就长了这么多的树。","en":"But it's quite a way, no matter which road you take, so the trees got overgrown with time.","ja":"どの通りからも、中途半端に遠いからいつの間にか木が茂っちゃったんだろうな"},"kind":"dialogue"},{"uid":"talk.kirito_2_36#originalText","id":"talk.kirito_2_36","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"没有人会经过这里，想练多久都没问题。","en":"Okay, we can practice to our hearts' content here. Nobody's gonna find us.","ja":"ここなら人通りもないし思い切って稽古できるぞ"},"kind":"dialogue"},{"uid":"talk.kirito_2_37#originalText","id":"talk.kirito_2_37","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"唔……桐人你真是天才，专门找这种地方的天才。","en":"Wow... Kirito, you really do have a knack for finding places like this.","ja":"はあ……キリトは本当に、こういうのを見つける天才だね"},"kind":"dialogue"},{"uid":"talk.kirito_2_38#originalText","id":"talk.kirito_2_38","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"哈哈哈，再多夸我几句！","en":"Bwa ha ha! You're welcome.","ja":"はっはっは、もっと褒めてくれ"},"kind":"dialogue"},{"uid":"talk.kirito_2_39#originalText","id":"talk.kirito_2_39","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"好，那我们在这里比划一下吧？还是你要自己一个人挥剑？","en":"Okay, wanna duel here? Or should we just swing our swords on our own?","ja":"よし、それじゃここで勝負するか?それとも、ひとりで素振りするか?"},"kind":"dialogue"},{"uid":"talk.kirito_2_39#selectionText1","id":"talk.kirito_2_39","speaker":{"cn":"[1]","en":"[1]","ja":"[1]"},"text":{"cn":"好！来比划一下吧，桐人！","en":"You're on! Let's have a bout, Kirito!","ja":"よし、勝負だキリト!"},"kind":"dialogue"},{"uid":"talk.kirito_2_39#selectionText2","id":"talk.kirito_2_39","speaker":{"cn":"[2]","en":"[2]","ja":"[2]"},"text":{"cn":"那么我就来尽情挥剑了","en":"I think I'd like to practice some swings on my own first.","ja":"それじゃ、思いっきり素振りするよ"},"kind":"dialogue"},{"uid":"talk.kirito_2_40#originalText","id":"talk.kirito_2_40","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"好！来比划一下吧，桐人！","en":"You're on! Let's have a bout, Kirito!","ja":"よし、勝負だキリト!"},"kind":"dialogue"},{"uid":"talk.kirito_2_41#originalText","id":"talk.kirito_2_41","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"那么我就来尽情挥剑了","en":"I think I'd like to practice some swings on my own first.","ja":"それじゃ、思いっきり素振りするよ"},"kind":"dialogue"},{"uid":"talk.kirito_2_42#originalText","id":"talk.kirito_2_42","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"喔，你想自己练剑啊。那我去买点东西回来。","en":"Practice swings, eh? Okay then, I'll go buy something while you're doing that.","ja":"そうか、素振りかだったら、俺は何か買ってくるよ"},"kind":"dialogue"},{"uid":"talk.kirito_2_43#originalText","id":"talk.kirito_2_43","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"等你练完后再一起吃吧。","en":"When you're finished, let's do lunch.","ja":"終わったら、一緒に食おうぜ"},"kind":"dialogue"},{"uid":"talk.kirito_2_44#originalText","id":"talk.kirito_2_44","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"好，谢谢你，桐人。","en":"Sure. Thanks, Kirito.","ja":"ああ、ありがとうキリト"},"kind":"dialogue"},{"uid":"talk.kirito_2_45#originalText","id":"talk.kirito_2_45","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"就是要这样！我要来真的啰，尤吉欧！","en":"That's the spirit! And no holding back, Eugeo!","ja":"そうこなくっちゃ!本気で行くぞ、ユージオ!"},"kind":"dialogue"},{"uid":"talk.kirito_2_46#originalText","id":"talk.kirito_2_46","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"嗯，你要是放水，我可是会生气的！","en":"I wouldn't have it any other way!","ja":"ああ、手を抜いたら怒るからね!"},"kind":"dialogue"},{"uid":"talk.kirito_2_47#originalText","id":"talk.kirito_2_47","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"……看招！","en":"Gotcha!","ja":"……そこっ!"},"kind":"dialogue"},{"uid":"talk.kirito_2_48#originalText","id":"talk.kirito_2_48","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"攻势太弱啦，尤吉欧！","en":"Oh, Eugeo, so naive!","ja":"甘いぜ、ユージオ!"},"kind":"dialogue"},{"uid":"talk.kirito_2_49#originalText","id":"talk.kirito_2_49","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"是吗！！","en":"Are you sure about that?!","ja":"どうかな!?"},"kind":"dialogue"},{"uid":"talk.kirito_2_50#originalText","id":"talk.kirito_2_50","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"唔喔喔喔喔！","en":"Grrraaah!","ja":"うおおおおっ!"},"kind":"dialogue"},{"uid":"talk.kirito_2_51#originalText","id":"talk.kirito_2_51","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"唔！居然利用体重一鼓作气压上来……你什么时候学会这种打法的……？","en":"Agh! All that weight in one... Wow, when'd you become so strong...?","ja":"くっ、一気に体重を……お前いつの間にこんな戦い方……"},"kind":"dialogue"},{"uid":"talk.kirito_2_52#originalText","id":"talk.kirito_2_52","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"在哥鲁哥罗索学长的教导下，我也是有进步的！","en":"Hey, you're not the only one who's been growing! Golgorosso is a great teacher, too!","ja":"僕だって成長してるんだ!ゴルゴロッソ先輩に教わってね!"},"kind":"dialogue"},{"uid":"talk.kirito_2_53#originalText","id":"talk.kirito_2_53","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"似乎是这么回事呢！不过，比体术我也不会输给你！","en":"Yeah, I can see that! But I'm pretty good at martial arts, too, ya know!","ja":"そうみたいだな!だけど、こっちだって体術なら負けないぜ!"},"kind":"dialogue"},{"uid":"talk.kirito_2_54#originalText","id":"talk.kirito_2_54","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"喝啊啊啊啊啊啊！","en":"Rahhh!","ja":"おりゃああああああ!"},"kind":"dialogue"},{"uid":"talk.kirito_2_55#originalText","id":"talk.kirito_2_55","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"唔喔喔喔──！！！","en":"Grrraaah!","ja":"うおおおおー!!!"},"kind":"dialogue"},{"uid":"talk.kirito_2_56#originalText","id":"talk.kirito_2_56","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"呼、呼、呼……","en":"Huff... Huff...","ja":"はあ、はあ、はあ……"},"kind":"dialogue"},{"uid":"talk.kirito_2_57#originalText","id":"talk.kirito_2_57","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"呼、呼……不赖嘛，尤吉欧。","en":"Huff, huff... Not too shabby, Eugeo...","ja":"はあ、はあ……やるな、ユージオ"},"kind":"dialogue"},{"uid":"talk.kirito_2_58#originalText","id":"talk.kirito_2_58","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"桐人你才是。","en":"Same to you, Kirito.","ja":"キリトこそ"},"kind":"dialogue"},{"uid":"talk.kirito_2_59#originalText","id":"talk.kirito_2_59","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"不过，我们的剑都落地了。这次的比剑就算平手啰。","en":"But we've both dropped our swords. Which means our sword fight is technically a draw.","ja":"でも、僕もキリトも剣を落としてるこれじゃ、剣の戦いは引き分けだね"},"kind":"dialogue"},{"uid":"talk.kirito_2_60#originalText","id":"talk.kirito_2_60","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"嗯，是啊……","en":"Right...","ja":"ああ、そうだな……"},"kind":"dialogue"},{"uid":"talk.kirito_2_61#originalText","id":"talk.kirito_2_61","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"………………","en":"......","ja":"………………"},"kind":"dialogue"},{"uid":"talk.kirito_2_62#originalText","id":"talk.kirito_2_62","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"………………","en":"......","ja":"………………"},"kind":"dialogue"},{"uid":"talk.kirito_2_63#originalText","id":"talk.kirito_2_63","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"喂！你还要在我身上坐多久？","en":"Hey. Gonna sit on me all day?","ja":"おい、いつまで乗っかってるんだよ"},"kind":"dialogue"},{"uid":"talk.kirito_2_64#originalText","id":"talk.kirito_2_64","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"啊，抱歉……","en":"Ah...! Yeah, sorry.","ja":"あ、ごめん……"},"kind":"dialogue"},{"uid":"talk.kirito_2_65#originalText","id":"talk.kirito_2_65","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"真是的……","en":"Jeez...","ja":"まったく……"},"kind":"dialogue"},{"uid":"talk.kirito_2_66#originalText","id":"talk.kirito_2_66","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"好像有种奇怪的感觉。","en":"That felt...rather strange.","ja":"なんだか、変な気分だったよ"},"kind":"dialogue"},{"uid":"talk.kirito_2_67#originalText","id":"talk.kirito_2_67","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"喂、喂喂……你在胡说什么啊？","en":"Wh-Whoa, buddy... What are you saying?","ja":"お、おいおい……お前何言い出すんだよ"},"kind":"dialogue"},{"uid":"talk.kirito_2_68#originalText","id":"talk.kirito_2_68","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"没、没有啦！","en":"I-It's not like that! I mean...","ja":"ち、違うよ!"},"kind":"dialogue"},{"uid":"talk.kirito_2_69#originalText","id":"talk.kirito_2_69","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我只是在想，如果我们从小就认识的话，","en":"This is probably how our friendship would have been if we'd met when we were kids.","ja":"僕たちが子どもの頃にもし出会ってたら毎日がこんな風だったのかなって……"},"kind":"dialogue"},{"uid":"talk.kirito_2_70#originalText","id":"talk.kirito_2_70","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"搞不好每天都是这副德性吧……","en":"That's all I was thinking, honest!","ja":"そう思ったんだってば"},"kind":"dialogue"},{"uid":"talk.kirito_2_71#originalText","id":"talk.kirito_2_71","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"……也许呢。每天都在那座森林里玩到满身泥巴……","en":"You may be right... We'd rough-house in that forest, getting covered in mud every day.","ja":"……そうかもしれないな毎日あの森で、泥だらけになって……"},"kind":"dialogue"},{"uid":"talk.kirito_2_72#originalText","id":"talk.kirito_2_72","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"嗯……肯定是这样的。","en":"Yeah... I can totally see that.","ja":"うん……きっとそうだよ"},"kind":"dialogue"},{"uid":"talk.kirito_3_00#originalText","id":"talk.kirito_3_00","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"「放开你的那只手」","en":"Put That Hand Away","ja":"「その手をどけて」"},"kind":"caption"},{"uid":"talk.kirito_3_01#originalText","id":"talk.kirito_3_01","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"莉兹和西莉卡今天好像都不能来。","en":"Liz and Silica say they can't make it today.","ja":"リズさんとシリカちゃんも今日は来れないって"},"kind":"dialogue"},{"uid":"talk.kirito_3_02#originalText","id":"talk.kirito_3_02","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"是吗？那今天就只有我和莉法两个人了。","en":"Oh... Okay, I guess that means it's just you and me then, Leafa.","ja":"そうか、なら今日は俺とリーファのふたりっきりってことだな"},"kind":"dialogue"},{"uid":"talk.kirito_3_03#originalText","id":"talk.kirito_3_03","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"呃、嗯……","en":"S-Sure.","ja":"う、うん……"},"kind":"dialogue"},{"uid":"talk.kirito_3_04#originalText","id":"talk.kirito_3_04","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"要不要去问问朔夜和亚丽莎？那两个人的话搞不好……","en":"Wanna reach out to Sakuya or Alicia? They might be free.","ja":"サクヤとかアリシャにも声かけてみるか?あのふたりなら、もしかしたら……"},"kind":"dialogue"},{"uid":"talk.kirito_3_04#selectionText1","id":"talk.kirito_3_04","speaker":{"cn":"[1]","en":"[1]","ja":"[1]"},"text":{"cn":"不必了，就我们两个人吧","en":"Nah, I'm cool with just the two of us.","ja":"ううん、いいよふたりで"},"kind":"dialogue"},{"uid":"talk.kirito_3_04#selectionText2","id":"talk.kirito_3_04","speaker":{"cn":"[2]","en":"[2]","ja":"[2]"},"text":{"cn":"也是呢，邀邀看吧","en":"Good call. I'll ask them.","ja":"そうだね、誘ってみよう"},"kind":"dialogue"},{"uid":"talk.kirito_3_05#originalText","id":"talk.kirito_3_05","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"也是呢，邀邀看吧","en":"Good call. I'll ask them.","ja":"そうだね、誘ってみよう"},"kind":"dialogue"},{"uid":"talk.kirito_3_06#originalText","id":"talk.kirito_3_06","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"不必了，就我们两个人吧","en":"Nah, I'm cool with just the two of us.","ja":"ううん、いいよふたりで"},"kind":"dialogue"},{"uid":"talk.kirito_3_07#originalText","id":"talk.kirito_3_07","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"那我先问朔夜……「抱歉突然打扰，妳现在有空吗？」","en":"Okay, first Sakuya... \"Hey, are you busy right now?\"","ja":"じゃあまず、サクヤから……「突然だけど、今時間ある?」"},"kind":"dialogue"},{"uid":"talk.kirito_3_08#originalText","id":"talk.kirito_3_08","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"就这样稍等一下……喔！她回复了！","en":"Now we just wait a while and... Whoa! Already got a reply!","ja":"これでしばらく待てば……うおっ、もう返事来た!"},"kind":"dialogue"},{"uid":"talk.kirito_3_09#originalText","id":"talk.kirito_3_09","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"「我马上过去，地点在哪？」……看来是邀到了呢。","en":"\"Be right there. Where are you guys?\"... Looks like we caught one.","ja":"「すぐに行く。場所はどこかな?」……捕まったみたいだな"},"kind":"dialogue"},{"uid":"talk.kirito_3_10#originalText","id":"talk.kirito_3_10","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"呃、嗯……是呀。不过，要是没有问亚丽莎小姐，可能会不太妙呢。","en":"C-Cool... But we should probably also reach out to Alicia, or things could be awkward.","ja":"う、うん……そうだねでも、アリシャさんにも声かけないとまずそうだね"},"kind":"dialogue"},{"uid":"talk.kirito_3_11#originalText","id":"talk.kirito_3_11","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"对呀……感觉会出乎意料地热闹。","en":"Right... Well, things're gonna be much livelier than I thought.","ja":"そうだなあ……思いがけず賑やかになりそうだ"},"kind":"dialogue"},{"uid":"talk.kirito_3_12#originalText","id":"talk.kirito_3_12","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"喔……好吧，偶尔这样好像也不错。","en":"Okay... Well, hanging out one- on-one isn't a bad thing.!","ja":"そうか……まあ、たまにはいいかもな"},"kind":"dialogue"},{"uid":"talk.kirito_3_12_2#originalText","id":"talk.kirito_3_12_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"那我们就去外面逛逛吧！","en":"Let's go out somewhere!","ja":"それじゃ、どこかに出かけるか!"},"kind":"dialogue"},{"uid":"talk.kirito_3_13#originalText","id":"talk.kirito_3_13","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"嗯！","en":"Okay!","ja":"うん!"},"kind":"dialogue"},{"uid":"talk.kirito_3_14#originalText","id":"talk.kirito_3_14","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"对了，这里好像离我们第一次见面的地方很近呢。","en":"Come to think of it, this is pretty close to the place where we first met in-game.","ja":"そう言えば、ここって俺とリーファが最初に出会った場所の近くだよな"},"kind":"dialogue"},{"uid":"talk.kirito_3_15#originalText","id":"talk.kirito_3_15","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"啊，好像是耶！当时我们受到火精灵袭击……","en":"Ooh, I think you're right! I remember the Salamanders ambushed me and...","ja":"あ、そうかも!あの時、あたしたちがサラマンダーに襲われて……"},"kind":"dialogue"},{"uid":"talk.kirito_3_16#originalText","id":"talk.kirito_3_16","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"结果是超级菜鸟桐人跑来救我们。","en":"Then you rescued me, even though you were a total noob.","ja":"それで、超初心者のキリトくんが助けに来てくれたんだよね"},"kind":"dialogue"},{"uid":"talk.kirito_3_16#selectionText1","id":"talk.kirito_3_16","speaker":{"cn":"[1]","en":"[1]","ja":"[1]"},"text":{"cn":"身旁还跟着小小的结衣","en":"And Yui was with you, too.","ja":"小さいユイちゃんと一緒にね"},"kind":"dialogue"},{"uid":"talk.kirito_3_16#selectionText2","id":"talk.kirito_3_16","speaker":{"cn":"[2]","en":"[2]","ja":"[2]"},"text":{"cn":"而且还是单枪匹马！","en":"And you were alone, too!","ja":"しかも、たったひとりで!"},"kind":"dialogue"},{"uid":"talk.kirito_3_17#originalText","id":"talk.kirito_3_17","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"而且还是单枪匹马！","en":"And you were alone, too!","ja":"しかも、たったひとりで!"},"kind":"dialogue"},{"uid":"talk.kirito_3_18#originalText","id":"talk.kirito_3_18","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"身旁还跟着小小的结衣","en":"And Yui was with you, too.","ja":"小さいユイちゃんと一緒にね"},"kind":"dialogue"},{"uid":"talk.kirito_3_19#originalText","id":"talk.kirito_3_19","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"不对啦，结衣也在唷。","en":"No, Yui was with me.","ja":"いやいや、ユイもいたよ"},"kind":"dialogue"},{"uid":"talk.kirito_3_20#originalText","id":"talk.kirito_3_20","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"咦？是吗……？这么说起来……","en":"Wait, was she? Now that you mention it...","ja":"あれ、そうだったっけ……そういえば……"},"kind":"dialogue"},{"uid":"talk.kirito_3_21#originalText","id":"talk.kirito_3_21","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"忘记结衣的下场可是很恐怖的──说到这个，可以把结衣找来呢。","en":"Don't forget about Yui— you'll get hell for it. Actually, I could call her here.","ja":"ユイのことを忘れると、怖いからなーそう言えば、ユイなら呼び出せるな"},"kind":"dialogue"},{"uid":"talk.kirito_3_22#originalText","id":"talk.kirito_3_22","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"什么？","en":"Huh?","ja":"え?"},"kind":"dialogue"},{"uid":"talk.kirito_3_23#originalText","id":"talk.kirito_3_23","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"反正也没什么人，就把结衣叫来吧。喂～结衣～","en":"No one's around anyway. I'll give it a shot. Hellooo? Yui?","ja":"人も少ないし、ユイを呼ぶかおーい、ユイー"},"kind":"dialogue"},{"uid":"talk.kirito_3_24#originalText","id":"talk.kirito_3_24","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"啊……对喔，确实是这样。","en":"Oh... Yeah. That's right.","ja":"あ……そっか、そうだよね"},"kind":"dialogue"},{"uid":"talk.kirito_3_25#originalText","id":"talk.kirito_3_25","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"没错，结衣也在呢。就在口袋里面。","en":"That's right, Yui was with me. Right in my pocket.","ja":"そうそう、ユイもいたよなポケットに入って"},"kind":"dialogue"},{"uid":"talk.kirito_3_26#originalText","id":"talk.kirito_3_26","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"当时我真的吓了一大跳呢。","en":"And she totally freaked me out.","ja":"あの時、すごくびっくりしたんだから"},"kind":"dialogue"},{"uid":"talk.kirito_3_27#originalText","id":"talk.kirito_3_27","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"不过，多亏了结衣，我们才勉强撑了一阵子。","en":"But it was all thanks to Yui that I was able to fight back then.","ja":"でも、ユイのおかげである程度戦えたんだよ"},"kind":"dialogue"},{"uid":"talk.kirito_3_28#originalText","id":"talk.kirito_3_28","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"她还教了我关于技能和这个世界的事。","en":"She taught me a lot about skills and Alfheim itself.","ja":"スキルのこととか、世界のことも教えてもらったし"},"kind":"dialogue"},{"uid":"talk.kirito_3_29#originalText","id":"talk.kirito_3_29","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"不过我记得你好像没有飞行技能耶──","en":"And yet your flying skills were somehow lacking.","ja":"空を飛ぶスキルは持ってなかったみたいだけどねー"},"kind":"dialogue"},{"uid":"talk.kirito_3_30#originalText","id":"talk.kirito_3_30","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"别、别鸡蛋里挑骨头了……我之前从来没有在空中飞过啊。","en":"Hey, don't mock me for that. I'd never once flown before.","ja":"そ、それを言うなよ……空を飛ぶなんて、それまでやったことなかったんだから"},"kind":"dialogue"},{"uid":"talk.kirito_3_31#originalText","id":"talk.kirito_3_31","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"呵呵，抱歉抱歉，那……","en":"Hehe, sorry. So...","ja":"ふふ、ごめんごめんそれで……"},"kind":"dialogue"},{"uid":"talk.kirito_3_32#originalText","id":"talk.kirito_3_32","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"嘘！莉法……安静一点。","en":"Shh! Leafa...quiet.","ja":"シッ、リーファ……静かにして"},"kind":"dialogue"},{"uid":"talk.kirito_3_33#originalText","id":"talk.kirito_3_33","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"嗯？怎么了吗？","en":"Hm? Something wrong?","ja":"ん?どうしたの?"},"kind":"dialogue"},{"uid":"talk.kirito_3_34#originalText","id":"talk.kirito_3_34","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"远方有打斗的声音。还有喊叫声……","en":"I hear fighting in the distance. Voices, too.","ja":"遠くで戦闘の音が聞こえる人の声も……"},"kind":"dialogue"},{"uid":"talk.kirito_3_35#originalText","id":"talk.kirito_3_35","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"是不是有队伍在打怪啊？","en":"Might be a party off hunting?","ja":"どこかのパーティが狩りしてるのかな?"},"kind":"dialogue"},{"uid":"talk.kirito_3_36#originalText","id":"talk.kirito_3_36","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"不对，感觉不像。","en":"No, doesn't sound like it.","ja":"いや、そんな感じじゃないな"},"kind":"dialogue"},{"uid":"talk.kirito_3_36_2#originalText","id":"talk.kirito_3_36_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我们去看看吧，莉法。","en":"Let's check it out.","ja":"行ってみよう、リーファ"},"kind":"dialogue"},{"uid":"talk.kirito_3_37#originalText","id":"talk.kirito_3_37","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"啊，等一下啦，桐人！","en":"Kirito! Wait for me!","ja":"あ、待ってよキリトくん!"},"kind":"dialogue"},{"uid":"talk.kirito_3_38#originalText","id":"talk.kirito_3_38","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"莉法，妳看！就在那里！","en":"Leafa, look! Over there!","ja":"リーファ、見ろ!あそこだ!"},"kind":"dialogue"},{"uid":"talk.kirito_3_39#originalText","id":"talk.kirito_3_39","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"有很多人在攻击一个玩家……这是………","en":"They're ganging up on a solo player... That looks like...","ja":"ひとりのプレイヤーを大勢で襲ってる……あれって……"},"kind":"dialogue"},{"uid":"talk.kirito_3_40#originalText","id":"talk.kirito_3_40","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"肯定是在PK。而且，从装备来看，被攻击的是新手。","en":"Yeah, definitely a PK team. And judging by their garb, the victim is a noob.","ja":"間違いなくPKだしかも、装備からすると襲われてる方は初心者だな"},"kind":"dialogue"},{"uid":"talk.kirito_3_41#originalText","id":"talk.kirito_3_41","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我们去帮他吧，莉法！","en":"Let's go save them, Leafa!","ja":"助けに行くぞ、リーファ!"},"kind":"dialogue"},{"uid":"talk.kirito_3_41#selectionText1","id":"talk.kirito_3_41","speaker":{"cn":"[1]","en":"[1]","ja":"[1]"},"text":{"cn":"光靠我们两个太危险了！得找个人来才行！","en":"It's too dangerous for us! We need to call backup!","ja":"ふたりじゃ危ないよ!誰かを呼ばないと!"},"kind":"dialogue"},{"uid":"talk.kirito_3_41#selectionText2","id":"talk.kirito_3_41","speaker":{"cn":"[2]","en":"[2]","ja":"[2]"},"text":{"cn":"嗯，我们去帮他吧！","en":"Yes, let's go!","ja":"うん、助けに行こう!"},"kind":"dialogue"},{"uid":"talk.kirito_3_42#originalText","id":"talk.kirito_3_42","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"光靠我们两个太危险了！得找个人来才行！","en":"It's too dangerous for us! We need to call backup!","ja":"ふたりじゃ危ないよ!誰かを呼ばないと!"},"kind":"dialogue"},{"uid":"talk.kirito_3_43#originalText","id":"talk.kirito_3_43","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"嗯，我们去帮他吧！","en":"Yes, let's go!","ja":"うん、助けに行こう!"},"kind":"dialogue"},{"uid":"talk.kirito_3_44#originalText","id":"talk.kirito_3_44","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"哪有时间去找人啊！这样的话，我自己一个人去！","en":"We don't have time to call for backup! If you're not helping, I'll go alone!","ja":"そんなこと言ってる場合かよ!だったら、俺ひとりでも行くぞ!"},"kind":"dialogue"},{"uid":"talk.kirito_3_45#originalText","id":"talk.kirito_3_45","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"啊，哥哥……","en":"K-Kirito...","ja":"あ、お兄ちゃん……"},"kind":"dialogue"},{"uid":"talk.kirito_3_46#originalText","id":"talk.kirito_3_46","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"总算是平安救下那个玩家了。","en":"We somehow managed to save the day.","ja":"なんとか無事に助けられたよ"},"kind":"dialogue"},{"uid":"talk.kirito_3_47#originalText","id":"talk.kirito_3_47","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"那、那个……我……","en":"Um, I...","ja":"あ、あの……あたし……"},"kind":"dialogue"},{"uid":"talk.kirito_3_48#originalText","id":"talk.kirito_3_48","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"毕竟对方人多势众，妳的判断也没错。","en":"Well, it was a big group to face. You did make the right call.","ja":"まあ、相手は大勢だったしなリーファの判断も間違ってないよ"},"kind":"dialogue"},{"uid":"talk.kirito_3_49#originalText","id":"talk.kirito_3_49","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"那我们回去吧。","en":"Wanna head back?","ja":"それじゃ、戻ろうか"},"kind":"dialogue"},{"uid":"talk.kirito_3_50#originalText","id":"talk.kirito_3_50","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"……嗯。","en":"Sure.","ja":"……うん"},"kind":"dialogue"},{"uid":"talk.kirito_3_51#originalText","id":"talk.kirito_3_51","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"莉法，妳从左边过去！我从右边！","en":"Leafa, go left! I'll take the right!","ja":"リーファは左から頼む!俺は右を!"},"kind":"dialogue"},{"uid":"talk.kirito_3_52#originalText","id":"talk.kirito_3_52","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"知道了！","en":"Roger!","ja":"了解!"},"kind":"dialogue"},{"uid":"talk.kirito_3_52_2#originalText","id":"talk.kirito_3_52_2","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"喝啊────","en":"Raaah!","ja":"りゃあああああ!"},"kind":"dialogue"},{"uid":"talk.kirito_3_53#originalText","id":"talk.kirito_3_53","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"呼……对手根本没有想像中厉害嘛。","en":"Phew... Wasn't as hard as I thought it'd be.","ja":"ふう……思ったより大したことなかったな"},"kind":"dialogue"},{"uid":"talk.kirito_3_54#originalText","id":"talk.kirito_3_54","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"毕竟他们是专挑新手的家伙嘛，真正厉害的人才不会做这种事。","en":"Well, they were picking on a noob. Truly powerful players don't do that sort of thing.","ja":"初心者狩りするようなヤツだからねホントに強い人は、こんなことしないもん"},"kind":"dialogue"},{"uid":"talk.kirito_3_55#originalText","id":"talk.kirito_3_55","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"没错。","en":"Good point.","ja":"その通りだな"},"kind":"dialogue"},{"uid":"talk.kirito_3_56#originalText","id":"talk.kirito_3_56","speaker":{"cn":"新手玩家","en":"Beginner Player","ja":"初心者プレイヤー"},"text":{"cn":"那、那个……非常感谢你们的帮助。","en":"T-Thanks for saving me.","ja":"あ、あの……どうもありがとうございました"},"kind":"dialogue"},{"uid":"talk.kirito_3_57#originalText","id":"talk.kirito_3_57","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"不客气。ALO不是只有这种恶劣的玩家，如果你愿意的话请再多玩玩看。","en":"No problem. Don't let jerks like them scare you. Most ALO players aren't like that.","ja":"ううん、ALOはこんなヤツらばっかりじゃないからよかったらもうちょっと続けてみて"},"kind":"dialogue"},{"uid":"talk.kirito_3_58#originalText","id":"talk.kirito_3_58","speaker":{"cn":"新手玩家","en":"Beginner Player","ja":"初心者プレイヤー"},"text":{"cn":"好、好的！那么，我先告辞了！","en":"O-Okay! Well, thanks again!","ja":"は、はい!それでは失礼します!"},"kind":"dialogue"},{"uid":"talk.kirito_3_59#originalText","id":"talk.kirito_3_59","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"这样他应该还会继续玩下去吧。","en":"I hope he keeps playing.","ja":"これなら、続けてくれるかな"},"kind":"dialogue"},{"uid":"talk.kirito_3_60#originalText","id":"talk.kirito_3_60","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"……话说回来，哥哥，那些人好像留下了什么东西。","en":"By the way, Kirito... I think that PK unit dropped something.","ja":"……ところでお兄ちゃんあの人たち、何か置いていったみたいだけど"},"kind":"dialogue"},{"uid":"talk.kirito_3_61#originalText","id":"talk.kirito_3_61","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"喔！是稀有道具吗？在哪里？","en":"Ooh! Like an item? Where is it?","ja":"おっ、レアアイテムか?どこだ?"},"kind":"dialogue"},{"uid":"talk.kirito_3_62#originalText","id":"talk.kirito_3_62","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"已经被我捡起来啦～","en":"Oh, I picked it up. It's miiine.","ja":"あたしが拾ったもーん"},"kind":"dialogue"},{"uid":"talk.kirito_3_63#originalText","id":"talk.kirito_3_63","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"喂！莉法，让我看看啦。到底是什么道具？","en":"Oh come on, Leafa, let me see it. What is it?!","ja":"おいリーファ、見せてくれよなんだったんだ!"},"kind":"dialogue"},{"uid":"talk.kirito_3_64#originalText","id":"talk.kirito_3_64","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"等一下，桐人……哥哥！你靠得太近了……","en":"Whoa, Kirito...hey! Out of my face...","ja":"ちょっとキリトくん……お兄ちゃん!近いってば……"},"kind":"dialogue"},{"uid":"talk.kirito_3_65#originalText","id":"talk.kirito_3_65","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"啊……","en":"Ack!","ja":"あっ……"},"kind":"dialogue"},{"uid":"talk.kirito_3_66#originalText","id":"talk.kirito_3_66","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"喂……","en":"Wha...?","ja":"ちょっ……"},"kind":"dialogue"},{"uid":"talk.kirito_3_67#originalText","id":"talk.kirito_3_67","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"不、不是的！我只是脚滑了一下……","en":"Y-You've got it all wrong! My leg just slipped...","ja":"こ、これは違うんだ!脚が滑って……"},"kind":"dialogue"},{"uid":"talk.kirito_3_68#originalText","id":"talk.kirito_3_68","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"！！！好啦，快点放手！","en":"!!! Just shut up and move!","ja":"!!!いいから離れて!"},"kind":"dialogue"},{"uid":"talk.kirito_3_69#originalText","id":"talk.kirito_3_69","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"真、真是的……都怪你要做这种事……","en":"J-Jeez... Why do you always have to pull stunts like that?","ja":"も、もう……こういうこと、するんだから……"},"kind":"dialogue"}]};
